    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <!-- Keypress Haptic Feedback -->\n    <uses-permission android:name=\"android.permission.VIBRATE\" />\n\n    <!-- Optional Microphone for Real-Time Bengali & English Voice Typing -->\n    <uses-permission android:name=\"android.permission.RECORD_AUDIO\" />\n\n    <application\n        android:allowBackup=\"true\"\n        android:icon=\"@android:drawable/ic_menu_edit\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@android:drawable/ic_menu_edit\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.KothaPro\">\n\n        <!-- Launcher & Onboarding Activity -->\n        <activity\n            android:name=\".OnboardingActivity\"\n            android:exported=\"true\"\n            android:label=\"@string/app_name\"\n            android:theme=\"@style/Theme.KothaPro\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Keyboard Settings Activity -->\n        <activity\n            android:name=\".SettingsActivity\"\n            android:exported=\"true\"\n            android:label=\"@string/settings_title\"\n            android:theme=\"@style/Theme.KothaPro\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.APPLICATION_PREFERENCES\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Core InputMethodService -->\n        <service\n            android:name=\".KothaKeyboardService\"\n            android:exported=\"true\"\n            android:label=\"@string/ime_service_label\"\n            android:permission=\"android.permission.BIND_INPUT_METHOD\">\n            <intent-filter>\n                <action android:name=\"android.view.InputMethod\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.view.im\"\n                android:resource=\"@xml/method\" />\n        </service>\n\n    </application>\n\n</manifest>\n"
