    "category": "XML",
    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<LinearLayout xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:id=\"@+id/keyboard_root_container\"\n    android:layout_width=\"match_parent\"\n    android:layout_height=\"wrap_content\"\n    android:orientation=\"vertical\"\n    android:background=\"@color/bg_dark\">\n\n    <!-- Top Suggestion Strip & Quick Action Bar -->\n    <LinearLayout\n        android:id=\"@+id/toolbar_and_suggestion_strip\"\n        android:layout_width=\"match_parent\"\n        android:layout_height=\"44dp\"\n        android:orientation=\"horizontal\"\n        android:gravity=\"center_vertical\"\n        android:background=\"@color/suggestion_strip_bg_dark\"\n        android:paddingHorizontal=\"4dp\">\n\n        <!-- Quick Access Action Buttons -->\n        <ImageButton\n            android:id=\"@+id/btn_action_language\"\n            android:layout_width=\"38dp\"\n            android:layout_height=\"38dp\"\n            android:background=\"?attr/selectableItemBackgroundBorderless\"\n            android:contentDescription=\"Language Mode\"\n            android:src=\"@android:drawable/ic_menu_sort_by_size\"\n            android:tint=\"@color/key_text_dark\" />\n\n        <ImageButton\n            android:id=\"@+id/btn_action_mic\"\n            android:layout_width=\"38dp\"\n            android:layout_height=\"38dp\"\n            android:background=\"?attr/selectableItemBackgroundBorderless\"\n            android:contentDescription=\"Voice Typing\"\n            android:src=\"@android:drawable/ic_btn_speak_now\"\n            android:tint=\"@color/primary_emerald\" />\n\n        <ImageButton\n            android:id=\"@+id/btn_action_clipboard\"\n            android:layout_width=\"38dp\"\n            android:layout_height=\"38dp\"\n            android:background=\"?attr/selectableItemBackgroundBorderless\"\n            android:contentDescription=\"Clipboard\"\n            android:src=\"@android:drawable/ic_menu_paste_light\"\n            android:tint=\"@color/key_subtext_dark\" />\n\n        <!-- Horizontal Scrollable Suggestions Container -->\n        <HorizontalScrollView\n            android:id=\"@+id/suggestion_scroll_view\"\n            android:layout_width=\"0dp\"\n            android:layout_height=\"match_parent\"\n            android:layout_weight=\"1\"\n            android:scrollbars=\"none\"\n            android:fillViewport=\"true\">\n\n            <LinearLayout\n                android:id=\"@+id/suggestion_container\"\n                android:layout_width=\"wrap_content\"\n                android:layout_height=\"match_parent\"\n                android:orientation=\"horizontal\"\n                android:gravity=\"center_vertical\"\n                android:paddingHorizontal=\"4dp\" />\n        </HorizontalScrollView>\n\n        <ImageButton\n            android:id=\"@+id/btn_action_settings\"\n            android:layout_width=\"38dp\"\n            android:layout_height=\"38dp\"\n            android:background=\"?attr/selectableItemBackgroundBorderless\"\n            android:contentDescription=\"Settings\"\n            android:src=\"@android:drawable/ic_menu_manage\"\n            android:tint=\"@color/key_subtext_dark\" />\n    </LinearLayout>\n\n    <!-- Recording Indicator Bar (Visible when voice recognition active) -->\n    <LinearLayout\n        android:id=\"@+id/voice_recording_bar\"\n        android:layout_width=\"match_parent\"\n        android:layout_height=\"36dp\"\n        android:orientation=\"horizontal\"\n        android:gravity=\"center\"\n        android:background=\"@color/status_recording\"\n        android:visibility=\"gone\">\n\n        <TextView\n            android:id=\"@+id/tv_voice_status\"\n            android:layout_width=\"wrap_content\"\n            android:layout_height=\"wrap_content\"\n            android:text=\"Listening (Bengali)... Speak now\"\n            android:textColor=\"#FFFFFF\"\n            android:textSize=\"13sp\"\n            android:textStyle=\"bold\" />\n    </LinearLayout>\n\n    <!-- Main Keyboard Keys Container (Populated dynamically by KeyboardView/Layout) -->\n    <LinearLayout\n        android:id=\"@+id/keyboard_keys_container\"\n        android:layout_width=\"match_parent\"\n        android:layout_height=\"240dp\"\n        android:orientation=\"vertical\"\n        android:padding=\"3dp\" />\n\n</LinearLayout>\n"
